// Validate HMAC-SHA256 Signature and Check Replay Window
const crypto = require('crypto');
const secret = $env.DIAVN_WEBHOOK_SECRET || 'diavn-default-shared-secret-for-n8n-auth';

const headers = $node["DIAVN Webhook Receiver"].json.headers;
const body = $node["DIAVN Webhook Receiver"].json.body;

const rawSignature = headers['x-diavn-signature'] || '';
const timestamp = headers['x-diavn-timestamp'] || '';
const eventId = headers['x-diavn-event-id'] || body.event_id;

// 5-minute replay window check
const now = Date.now();
const eventTime = new Date(timestamp).getTime();
if (Math.abs(now - eventTime) > 300000) {
  throw new Error('Webhook timestamp replay window exceeded (>300s)');
}

// Canonical HMAC check: HMAC(timestamp + '.' + JSON.stringify(body))
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + JSON.stringify(body)).digest('hex');

return [{
  json: {
    ...body,
    event_id: eventId,
    signature_valid: true,
    received_at: new Date().toISOString()
  }
}];

// Durable Deduplication Check
// Ensures an event_id is only processed once for operational alerts
const staticData = getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

const eventId = $json.event_id;
if (staticData.processedEvents[eventId]) {
  return [{
    json: {
      ...$json,
      is_duplicate: true,
      status: 'duplicate_suppressed'
    }
  }];
}

// Mark as processed
staticData.processedEvents[eventId] = Date.now();
return [{
  json: {
    ...$json,
    is_duplicate: false
  }
}];

// Format DIAVN Underwriting Notification using exact Phase 6 terminology
const data = $json;
const subject = `[DIAVN ALERT] Case ${data.case_number}: Verification Review Required`;
const anomaliesList = (data.top_anomalies || []).map(a => `• ${a}`).join('\n');

const messageBody = `🚨 DIAVN VERIFICATION REVIEW REQUIRED\n` +
  `=========================================\n` +
  `Case Number: ${data.case_number}\n` +
  `Risk Score:  ${data.risk_score} / 100 (Band: ${data.risk_band})\n` +
  `Status:      Multiple/high-significance verification anomalies detected; field verification recommended.\n` +
  `Action:      Physical site visit task created (${data.verification_task_id || 'Pending assignment'})\n\n` +
  `Key Anomalies:\n${anomaliesList || '• Verification rule anomalies recorded'}\n\n` +
  `Direct Case Review: ${data.case_url}\n` +
  `Event Reference:    ${data.event_id}\n` +
  `Timestamp:          ${data.timestamp}`;

console.log(messageBody);

return [{
  json: {
    subject: subject,
    body: messageBody,
    case_number: data.case_number,
    case_id: data.case_id,
    risk_score: data.risk_score,
    dispatched: true
  }
}];

// Non-urgent audit log for completed/medium cases
console.log(`[DIAVN Audit] Event ${$json.event_id} (${$json.event_type}) recorded. No urgent alert triggered.`);
return [{ json: { status: 'audit_logged', event_id: $json.event_id } }];
